import{_ as o,c as t,o as d,b2 as r}from"./chunks/framework.CUhoHPxN.js";const _=JSON.parse('{"title":"用户管理数据权限设计（DataPermissionInterceptor + 角色 dataScope）","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-14-user-data-permission-design.md","filePath":"superpowers/specs/2026-05-14-user-data-permission-design.md"}'),a={name:"superpowers/specs/2026-05-14-user-data-permission-design.md"};function s(c,e,n,i,l,p){return d(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="用户管理数据权限设计-datapermissioninterceptor-角色-datascope" tabindex="-1">用户管理数据权限设计（DataPermissionInterceptor + 角色 dataScope） <a class="header-anchor vp-link" href="#用户管理数据权限设计-datapermissioninterceptor-角色-datascope" aria-label="Permalink to &quot;用户管理数据权限设计（DataPermissionInterceptor + 角色 dataScope）&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>系统已具备角色 <strong><code>data_scope</code></strong>（1 全部、2 自定义、3 本部门、4 本部门及以下、5 仅本人）及 <strong><code>sys_role_dept</code></strong>（自定义部门绑定）。用户列表当前仅按请求参数中的部门树筛选，<strong>未</strong>按登录者角色数据权限自动收紧。</p><p><strong>目标</strong>：在用户管理模块内，对所有<strong>读库</strong>访问 <code>sys_user</code> 的路径统一施加与角色配置一致的数据范围；实现方式以 <strong>MyBatis-Plus <code>DataPermissionInterceptor</code></strong> 为主，语义与表结构对齐 <strong>若依 RuoYi-Vue3</strong>（后端 <code>@DataScope</code> / 角色 <code>data_scope</code> 的常见行为），用拦截器统一注入 SQL 条件，避免业务层重复拼条件。</p><blockquote><p><strong>说明</strong>：本仓库当前未检出 <code>原始需求/RuoYi-Vue3</code> 目录；实现时以外部若依工程为对照，核对 <code>data_scope</code> 取值与「多角色 OR 合并」行为即可。</p></blockquote><h2 id="_2-已确认的决策摘要" tabindex="-1">2. 已确认的决策摘要 <a class="header-anchor vp-link" href="#_2-已确认的决策摘要" aria-label="Permalink to &quot;2. 已确认的决策摘要&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>选择</th><th>说明</th></tr></thead><tbody><tr><td>多角色合并</td><td><strong>A：取最宽（并集）</strong></td><td>任一角色为「全部」则整体不追加部门/本人限制；否则各角色产生的可见集合 <strong>OR</strong> 合并。</td></tr><tr><td>作用范围</td><td><strong>B：用户模块内所有读 <code>sys_user</code> 的接口</strong></td><td>含分页、详情、导出、分配角色页加载的用户主数据等；凡通过 Mapper 读 <code>sys_user</code> 单表或主表为 <code>sys_user</code> 的查询均需纳入。</td></tr><tr><td>超级管理员</td><td><strong>B：不绕过数据权限</strong></td><td>与业务账号一致，仍受角色 <code>data_scope</code> 约束（与若依默认「admin 看全部」不同，以本需求为准）。</td></tr><tr><td>部门必填</td><td><strong>不允许没有部门</strong></td><td>业务规则：<code>sys_user.dept_id</code> 必填；创建/修改/导入等写入路径须校验；存量或登录用户若缺失部门则按统一错误策略处理（见 §7）。</td></tr><tr><td>与前端部门筛选</td><td><strong>A：AND</strong></td><td>数据权限为<strong>基线</strong>；列表/导出请求中的 <strong><code>deptId</code>（含子孙）</strong> 在基线结果上进一步 <strong>AND</strong> 收窄。</td></tr></tbody></table></div><h2 id="_3-与若依-ruoyi-的对照与映射" tabindex="-1">3. 与若依（RuoYi）的对照与映射 <a class="header-anchor vp-link" href="#_3-与若依-ruoyi-的对照与映射" aria-label="Permalink to &quot;3. 与若依（RuoYi）的对照与映射&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>若依常见做法</th><th>本项目映射</th></tr></thead><tbody><tr><td>角色 <code>data_scope</code> 五种取值</td><td>沿用现有 <code>SysRole.dataScope</code> 与 <code>sys_role_dept</code>。</td></tr><tr><td>切面 / <code>@DataScope</code> 改 SQL 或拼 <code>WHERE</code></td><td>使用 <strong><code>DataPermissionInterceptor</code> + <code>DataPermissionHandler</code>（或 <code>MultiDataPermissionHandler</code>）</strong> 在编译期/运行期为带注解的 Mapper 方法追加片段。</td></tr><tr><td>自定义部门：<code>sys_user</code> 与 <code>sys_role</code> / <code>sys_role_dept</code> 联查或子查询</td><td>Handler 内查询当前用户关联角色的部门集合，生成 <code>dept_id IN (...)</code> 或子查询；保持与若依「自定义 = 角色绑定部门列表」一致。</td></tr><tr><td>多角色 OR</td><td>与决策 <strong>§2 多角色 A</strong> 一致。</td></tr></tbody></table></div><h2 id="_4-范围-用户模块内需受控的读路径-初版清单" tabindex="-1">4. 范围：用户模块内需受控的读路径（初版清单） <a class="header-anchor vp-link" href="#_4-范围-用户模块内需受控的读路径-初版清单" aria-label="Permalink to &quot;4. 范围：用户模块内需受控的读路径（初版清单）&quot;">​</a></h2><p>以下凡最终落到 <strong><code>SysUserMapper</code> / <code>BaseMapper&lt;SysUser&gt;</code> 的 <code>select*</code></strong>（含 <code>selectById</code>、<code>selectOne</code>、<code>selectList</code>、<code>selectPage</code>、<code>selectCount</code> 等）均应命中数据权限（通过注解键或 Mapper 自定义方法统一控制，避免遗漏）：</p><ul><li>分页列表 <code>page</code></li><li>详情 <code>get</code></li><li>导出 <code>export</code></li><li>分配角色页 <code>authRoleInfo</code> 中对目标用户的读取</li><li>修改前加载 <code>update</code>、状态/密码/删除等路径中的 <strong><code>selectById</code> / <code>selectOne</code></strong>（读他人用户以判断存在性时，同样必须落在数据权限内，否则存在越权）</li></ul><p><strong>明确不在本设计「数据权限 SQL 注入」内、但需业务校验的</strong>：仅读 <strong><code>sys_role</code> / <code>sys_dept</code> / <code>sys_user_role</code></strong> 等辅助表时，仍按原有权限注解；若某接口仅改关系不读 <code>sys_user</code>，可不在此表上加注解。跨表「列表展示」若未来出现 <code>sys_user</code> JOIN 他表，需单独约定表别名与占位符。</p><h2 id="_5-数据语义-与现有字段一致" tabindex="-1">5. 数据语义（与现有字段一致） <a class="header-anchor vp-link" href="#_5-数据语义-与现有字段一致" aria-label="Permalink to &quot;5. 数据语义（与现有字段一致）&quot;">​</a></h2><ul><li><strong>1 全部</strong>：不追加数据权限条件（或等价恒真）。</li><li><strong>2 自定义</strong>：<code>dept_id IN (当前用户所拥有角色中，所有 </code>data_scope=2<code>角色在</code>sys_role_dept<code> 中的部门 id 并集)</code>。</li><li><strong>3 本部门</strong>：<code>dept_id = 当前登录用户 dept_id</code>。</li><li><strong>4 本部门及以下</strong>：<code>dept_id IN (以当前用户部门为根的子树)</code>；部门树算法与现有 <code>SysUserServiceImpl</code> 中按 <code>deptId</code> 筛选的子孙集合逻辑保持一致或可抽取为共享组件供 Handler 调用。</li><li><strong>5 仅本人</strong>：<code>user_id = 当前登录用户 id</code>。</li></ul><p><strong>多角色（并集）</strong>：对每个角色分别计算上述集合，再 <strong>OR</strong>；若其中任一角色为 <strong>1 全部</strong>，整体不再追加限制。</p><h2 id="_6-技术方案要点" tabindex="-1">6. 技术方案要点 <a class="header-anchor vp-link" href="#_6-技术方案要点" aria-label="Permalink to &quot;6. 技术方案要点&quot;">​</a></h2><h3 id="_6-1-拦截器注册" tabindex="-1">6.1 拦截器注册 <a class="header-anchor vp-link" href="#_6-1-拦截器注册" aria-label="Permalink to &quot;6.1 拦截器注册&quot;">​</a></h3><ul><li>在现有 <code>MybatisPlusInterceptor</code> Bean 中 <strong>增加</strong> <code>DataPermissionInterceptor</code>，<strong>顺序置于 <code>PaginationInnerInterceptor</code> 之前</strong>，避免先分页再过滤导致页内数据错误。</li><li>Db 方言与现网一致（H2 MySQL 模式 / 生产 MySQL）；数据权限片段使用与分页方言兼容的写法。</li></ul><h3 id="_6-2-handler-职责" tabindex="-1">6.2 Handler 职责 <a class="header-anchor vp-link" href="#_6-2-handler-职责" aria-label="Permalink to &quot;6.2 Handler 职责&quot;">​</a></h3><ul><li>从 <strong>登录上下文</strong>（Sa-Token：<code>StpUtil</code> / 既有封装）读取 <strong><code>userId</code>、<code>deptId</code></strong>。</li><li>查询当前用户关联角色及 <code>data_scope</code>；对 <code>data_scope=2</code> 批量读取 <code>sys_role_dept</code>。</li><li>合并得到 SQL 片段（或 <code>Expression</code>），与 <code>@DataPermission</code> 中配置的占位符对应；<strong>表名/列名</strong>与 <code>sys_user</code> 实体一致（注意 MP 生成 SQL 时主表别名，统一为文档中约定写法，如主表无别名则用 <code>sys_user.dept_id</code>）。</li></ul><h3 id="_6-3-mapper-标注策略" tabindex="-1">6.3 Mapper 标注策略 <a class="header-anchor vp-link" href="#_6-3-mapper-标注策略" aria-label="Permalink to &quot;6.3 Mapper 标注策略&quot;">​</a></h3><ul><li>优先在 <strong><code>SysUserMapper</code></strong> 上为「受控读」定义显式方法（或在 XML 中统一 <code>WHERE</code> 占位）并加 <strong><code>@DataPermission</code></strong>，避免仅依赖 <code>BaseMapper</code> 默认方法导致注解无法挂载。</li><li>对仍使用 <code>Wrappers.lambdaQuery()</code> 的代码路径，评估改为调用带注解的 Mapper 方法，或在 Service 层改为走统一封装查询，<strong>禁止</strong>出现绕过 Mapper、直连 <code>JdbcTemplate</code> 读用户列表的旁路（除非同样加等价条件）。</li></ul><h3 id="_6-4-与列表查询条件-and-决策-§2-5" tabindex="-1">6.4 与列表查询条件 AND（决策 §2-5） <a class="header-anchor vp-link" href="#_6-4-与列表查询条件-and-决策-§2-5" aria-label="Permalink to &quot;6.4 与列表查询条件 AND（决策 §2-5）&quot;">​</a></h3><ul><li>Service 层在构建 <code>LambdaQueryWrapper</code> 时保留现有用户名、状态、<code>deptId</code> 树等条件。</li><li>数据权限由拦截器追加为 <strong>同一 <code>WHERE</code> 的 AND 组</strong>；前端传入的 <code>deptId</code> 不得放宽数据权限基线。</li></ul><h2 id="_7-部门必填-dept-id" tabindex="-1">7. 部门必填（<code>dept_id</code>） <a class="header-anchor vp-link" href="#_7-部门必填-dept-id" aria-label="Permalink to &quot;7. 部门必填（`dept_id`）&quot;">​</a></h2><ul><li><strong>写入</strong>：<code>create</code> / <code>update</code> / <code>import</code> 等路径 <strong><code>dept_id</code> 非空校验</strong>；非法则 <code>WarningException</code> 等统一业务错误。</li><li><strong>读取</strong>：登录用户若缺失 <code>dept_id</code>，对依赖部门的 <code>data_scope</code>（2/3/4）无法计算合法集合时，约定为 <strong>可见集合为空</strong>（如 <code>1 = 0</code>）或统一返回「用户未分配部门」类错误；实现阶段二选一并在本文件定稿句中写死一种（推荐：<strong>业务错误 + 禁止进入用户管理写操作</strong>，列表只返回空集易误导，可结合产品选择）。</li></ul><h2 id="_8-超级管理员不绕过-决策-§2-3" tabindex="-1">8. 超级管理员不绕过（决策 §2-3） <a class="header-anchor vp-link" href="#_8-超级管理员不绕过-决策-§2-3" aria-label="Permalink to &quot;8. 超级管理员不绕过（决策 §2-3）&quot;">​</a></h2><ul><li>不根据「是否 admin 角色」跳过 <code>DataPermissionInterceptor</code>。</li><li>若需超级管理员具备「全部数据」，应通过为其分配 <strong><code>data_scope=1</code></strong> 的角色实现，而非代码特判。</li></ul><h2 id="_9-测试建议" tabindex="-1">9. 测试建议 <a class="header-anchor vp-link" href="#_9-测试建议" aria-label="Permalink to &quot;9. 测试建议&quot;">​</a></h2><ul><li><strong>Handler 单测</strong>：固定用户、多角色、<code>sys_role_dept</code>、部门树，断言生成片段或解析后的 id 集合。</li><li><strong>接口层</strong>：分页 / 详情 / 导出 / 分配角色页，使用不同 <code>data_scope</code> 账号请求，断言无越权 <code>userId</code>。</li><li><strong>回归</strong>：<code>deptId</code> 查询参数与数据权限 <strong>AND</strong> 后条数单调不增。</li></ul><h2 id="_10-风险与后续" tabindex="-1">10. 风险与后续 <a class="header-anchor vp-link" href="#_10-风险与后续" aria-label="Permalink to &quot;10. 风险与后续&quot;">​</a></h2><ul><li><strong>性能</strong>：每次查询加载角色与部门树可能增加开销；可对「当前用户数据权限片段」做 <strong>请求级缓存</strong>（ThreadLocal 或短期缓存 key=userId）。</li><li><strong>扩展</strong>：部门管理、岗位等若需同类数据权限，可复用 Handler 内核，按表配置不同 <code>@DataPermission</code> 键。</li></ul><h2 id="_11-自检" tabindex="-1">11. 自检 <a class="header-anchor vp-link" href="#_11-自检" aria-label="Permalink to &quot;11. 自检&quot;">​</a></h2><ul><li>无 TBD 占位；与决策表无矛盾。</li><li>范围 B 已落到具体 Mapper 读路径原则。</li><li>与若依差异点（超级管理员、仓库无 RuoYi 目录）已写明。</li></ul><hr><p><strong>请审阅本文档</strong>；确认无修改后，再进入 <strong>writing-plans</strong> 产出实现任务清单与拆分步骤。</p>',37)])])}const h=o(a,[["render",s]]);export{_ as __pageData,h as default};
